contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 amount) public payable {
        address from = msg.sender;
        address to = address(0xdead);

        require(to != address(0));
        require(from != to);

        uint256 fromBefore = c.balanceOf(from); if (__ESBMC_reverted()) return;
        uint256 toBefore = c.balanceOf(to); if (__ESBMC_reverted()) return;
        uint256 totalBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        bool fromFrozen = c.frozenAccount(from); if (__ESBMC_reverted()) return;
        bool toFrozen = c.frozenAccount(to); if (__ESBMC_reverted()) return;

        bool success;
        c.transfer(to, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            success = false;
        } else {
            success = true;
        }

        assert(
            (!fromFrozen && !toFrozen && fromBefore >= amount)
                ? (success && c.balanceOf(from) == fromBefore - amount && c.balanceOf(to) == toBefore + amount && c.totalSupply() == totalBefore)
                : (!success && c.balanceOf(from) == fromBefore && c.balanceOf(to) == toBefore && c.totalSupply() == totalBefore)
        );
    }
}

